# ----------------------------------------------------------------------
# cycle runners
# ----------------------------------------------------------------------
def run_cycle(cfg: Config, force: bool = False):
    s = st.session_state
    now = time.time()
    stale = now - float(s.get("last_run", 0)) > max(5, cfg.refresh_seconds)
    if not force and s.get("state") is not None and not stale:
        return s["state"]
    orch = Orchestrator(cfg)
    universe = s.get("universe", FNO_UNIVERSE)

    # 0.3% proximity rows are computed from cached candles (cheap on re-runs)
    #    and handed to the alert rules BEFORE the agents evaluate them.
    try:
        _watch = approaching(zone_rows(universe, tf=cfg.zone_watch_tf,
                                       max_symbols=cfg.zone_watch_max_symbols),
                             cfg.zone_watch_pct)
    except Exception:                                                # noqa: BLE001
        _watch = []
    orch.state.zone_watch = _watch

    rules = dict(st.session_state.get("ui_rules", {}))
    try:
        with st.spinner("Agents working: ingest → derivatives → news → alerts …"):
            state = orch.run(universe, zone_timeframes=[], zone_symbols=[], run_zone=False,
                             alert_rules=rules,
                             auto_trade=bool(st.session_state.get("ui_auto_trade", False)))
    except RuntimeError as exc:
        # cloud containers have a small thread budget; never blank the screen -
        # keep the last good snapshot and say so
        if "thread" not in str(exc).lower():
            raise
        prev = st.session_state.get("state")
        if prev is None:
            raise
        st.warning("इस पल सर्वर पर thread सीमा पूरी थी — पिछला स्नैपशॉट दिखाया जा रहा है। "
                   "अगला auto-refresh नया डेटा लाएगा।")
        return prev
    state.zone_watch = _watch
    s["orch"], s["state"], s["last_run"] = orch, state, now
    # zone scan only when the schedule says so (or the cache is empty) -
    # this is what keeps the app light on every 30-second refresh
    try:
        if not s.get("zone_rows_cache"):
            # first paint: a smaller, fast batch so the phone shows zones at once
            run_zone_scan(cfg, force=True, scope="Top 25")
        elif zone_scan_due(cfg):
            run_zone_scan(cfg)
    except Exception:                                             # noqa: BLE001
        s["zone_dirty"] = True
    return state


def zone_map_from_state(state, symbols=None) -> dict:
    """Nearest demand/supply zone per symbol - **never touches the network**.

    It only reads what the background zone scan already produced (``state.zones``
    or the session cache built by :func:`run_zone_scan`).  The old version pulled
    80 symbols × 2 timeframes while the master table was being drawn, which is
    exactly what left the table blank on a phone.
    """
    rows = list(getattr(state, "zones", None) or [])
    if not rows:
        rows = list(st.session_state.get("zone_rows_cache") or [])
    best: dict = {}
    for r in rows:
        sym, ltp = r.get("Symbol"), r.get("LTP") or 0
        prox = r.get("Entry (Proximal)") or r.get("Proximal") or 0
        if not sym or not ltp or not prox:
            continue
        gap = abs(float(prox) - float(ltp)) / float(ltp) * 100.0
        cur = best.get(sym)
        if cur is None or gap < cur["Gap %"]:
            best[sym] = {"Side": r.get("demand/Supply") or r.get("Side", ""),
                         "TF": r.get("tf") or r.get("Near Timeframe", ""),
                         "Gap %": round(gap, 2)}
    return best


def zone_scan_due(cfg: Config) -> bool:
    """Follow the desk schedule: 09:15–12:45 slots, 2/4/6h memory buckets."""
    from terminal.engine import zschedule
    if not st.session_state.get("ui_zone_auto", getattr(cfg, "zone_auto", True)):
        return st.session_state.get("zone_dirty", True)
    st_ = zschedule.slot_state()
    if not st_["in_grid"]:
        # market closed: refresh only at 15:00 / 18:00 / 20:00 / 22:00
        last = st.session_state.get("zone_last_ts", 0)
        slot = st_["last_slot"]
        return bool(slot and (not last or last < slot.timestamp()))
    return zschedule.should_scan(st.session_state.get("zone_last_ts", 0),
                                 bucket_h=int(st.session_state.get("ui_zone_bucket",
                                                                   getattr(cfg, "zone_bucket_h", 2))))


def run_zone_scan(cfg: Config, force: bool = False, scope: str = ""):
    s = st.session_state
    state = s.get("state")
    if state is None:
        return
    if not force and not s.get("zone_dirty", True) and not zone_scan_due(cfg):
        return
    tfs = s.get("ui_tfs", ["15m", "1h", "1d"])
    scope = scope or s.get("ui_scope", "Top 40")
    if scope.startswith("Top"):
        try:
            n = int(scope.split()[1])
        except Exception:
            n = 40
        syms = [f["Symbol"] for f in sorted(state.features, key=lambda f: -abs(f["Raw_Score"]))[:n]]
    elif scope == "Watchlist":
        wl = [x.strip().upper() for x in s.get("ui_watchlist", "").split(",") if x.strip()]
        syms = wl or [f["Symbol"] for f in state.features[:25]]
    else:
        syms = [f["Symbol"] for f in state.features]

    from terminal.engine import zschedule
    bucket = zschedule.current_bucket()
    cache_key = f"v11|zones|{bucket}|{scope}|{'-'.join(tfs)}|{len(syms)}"
    # weekly zones are built once per day and then reused all day
    _today_key = f"v11|weekly|{datetime.now():%Y-%m-%d}"
    _wk = zschedule.STORE.get(_today_key, max_age_min=60 * 20)
    _wk_rows = (_wk or {}).get("rows", [])

    cached = zschedule.STORE.get(cache_key, max_age_min=240)
    if cached and not force:
        state.zones = list(cached["rows"]) + list(_wk_rows)
        s["zone_rows_cache"] = list(state.zones)
        s["zone_last_ts"] = cached["ts"]
        s["zone_meta"] = cached.get("meta", {})
        s["zone_dirty"] = False
        return

    with st.spinner(f"Zone Agent: {len(syms)} symbols × {len(tfs)} TF "
                    f"(स्लॉट {zschedule.slot_state()['last_slot'] and zschedule.slot_state()['last_slot'].strftime('%H:%M') or '—'}) …"):
        rep = ZoneAgent(cfg).run(state, timeframes=list(tfs), symbols=syms,
                                 max_symbols=len(syms))
        rrep = RiskAgent(cfg).run(state)
    from terminal.agents.alert_agent import AlertAgent
    arep = AlertAgent(cfg).run(state, enabled_rules=dict(s.get("ui_rules", {})),
                               auto_trade=bool(s.get("ui_auto_trade", False)))
    s["orch"].reports[rep.name] = rep
    s["orch"].reports[rrep.name] = rrep
    s["orch"].reports[arep.name] = arep
    s["zone_dirty"] = False
    _wk_new = [r for r in (state.zones or [])
               if str(r.get("tf") or r.get("Near Timeframe")) == "1w"]
    if _wk_new:
        zschedule.STORE.save(_today_key, _wk_new, {"tf": "1w"})
        state.zones = list(state.zones) + _wk_rows
    s["zone_rows_cache"] = list(state.zones or [])
    s["zone_last_ts"] = time.time()
    meta = {"range": state.notes.get("zone_range", {}),
            "report": {"rows": rep.rows, "ok": rep.ok, "notes": rep.notes},
            "slots": zschedule.slot_state()["label"]}
    s["zone_meta"] = meta
    zschedule.STORE.save(cache_key, list(state.zones or []), meta)


def global_zone_rows(cfg: Config):
    """Zones for commodities / indices / FX from real Yahoo candles."""
    s = st.session_state
    cached = s.get("global_rows")
    if cached and time.time() - cached[0] < 600:
        return cached[1]
    yh = YahooProvider(cfg)
    rows = []
    if yh.is_available():
        from terminal.services.candles import CandleService
        svc = CandleService(yh, cache_dir=f"{cfg.cache_dir}/candles")
        for inst in GLOBAL_INSTRUMENTS:
            df = svc.get(inst["yahoo"], "1h")
            if df is None or df.empty:
                continue
            spot = 0.0
            q = s.get("state").global_quotes.get(inst["key"]) if s.get("state") else None
            spot = q.ltp if q else float(df["close"].iloc[-1])
            zones = detect_zones(df, spot=spot, max_zones=1,
                                 legout_mult=cfg.zone_legout_mult,
                                 max_wick_pct=cfg.zone_max_wick_pct,
                                 tight_base=cfg.zone_eod_filter)
            if not zones:
                continue
            e20, e50 = ema(df, 20), ema(df, 50)
            bias = "BUY" if (spot > e20 > 0 and (e50 == 0 or e20 > e50)) else (
                "SELL" if (spot < e20 and (e50 == 0 or e20 < e50)) else "AVOID TRADE")
            row = build_zone_row(inst["key"], "1h", zones[0], spot, spot,
                                 rr=cfg.zone_target_rr, sl_buffer_atr=cfg.zone_sl_buffer_atr,
                                 capital=cfg.capital, risk_pct=cfg.risk_per_trade_pct,
                                 ai_score=_fmt(max(-2.0, min(2.0, round((rsi(df, 14) - 50) / 3, 1)))),
                                 ai_bias=bias)
            row["Near Timeframe"] = "1h"
            rows.append(row)
    s["global_rows"] = (time.time(), rows)
    return rows


