_TV_INT = {"1m": "1", "3m": "3", "5m": "5", "10m": "10", "15m": "15", "30m": "30",
           "75m": "75", "1h": "60", "2h": "120", "4h": "240", "6h": "360",
           "1d": "D", "1w": "W", "1M": "M"}


def _tv_code(sym: str, fut: bool = True) -> str:
    """``NSE%3AM%26M`` - '&' must be escaped or the query string breaks."""
    from urllib.parse import quote
    return "NSE%3A" + quote(str(sym).upper(), safe="")


def _chart_url(sym: str, tf: str, fut: bool = True) -> str:
    """TradingView URL · fut=True -> NSE:<SYM>1! (current-month future).

    The colon is kept URL-escaped (%3A) and ``1!`` stays literal, so the very
    same text can be used as the LinkColumn label regex - the cell shows the
    ticker, never a long URL.
    """
    return (f"https://in.tradingview.com/chart/?symbol={_tv_code(sym)}"
            f"{'1!' if fut else ''}&interval={_TV_INT.get(tf, '15')}")


_LIVE_PX = (dict(zip(QDF["Symbol"], QDF["LTP"]))
            if not QDF.empty and "LTP" in QDF.columns else {})
_LIVE_STAMP = QSNAP.stamp if QSNAP.ok else ""
_FEAT_MAP = {f.get("Raw_Symbol"): f for f in (state.features or []) if f.get("Raw_Symbol")}


def _fut_info(sym: str, fallback=None):
    """Futures LTP + honest time tag (live tick / exchange EOD file / estimate)."""
    f = _FEAT_MAP.get(sym) or {}
    px = f.get("Futures LTP (Cur-M)") or fallback
    tag = str(f.get("Fut Src") or "")
    asof = str(f.get("Fut AsOf") or "")
    if tag == "F-EOD":
        when = asof or "EOD"
    elif tag == "LIVE":
        when = asof or _LIVE_STAMP or "लाइव"
    elif tag:
        when = "अनुमान"
    else:
        when = "EOD" if "bhavcopy" in str(f.get("Data Source", "")).lower() else "—"
    return (round(float(px), 2) if px else None), when


def _verdict_block(sym: str, key: str = "why") -> None:
    """Verdict + the floating Hindi 'क्यों?' popover for one symbol."""
    f = next((x for x in (state.features or [])
              if x.get("Raw_Symbol") == sym or x.get("Symbol") == sym), None)
    if not f:
        return
    bd = f.get("Score Breakdown") or []
    reasons = [{"v": "+" if b["Pts"] > 0 else ("-" if b["Pts"] < 0 else "0"),
                "hi": f"{b['Factor']} — {b['Detail']} ({b['Pts']:+.2f})"}
               for b in bd if abs(float(b.get("Pts") or 0)) > 0.2]
    _raw = float(f.get("Raw_Score") or 0.0)
    _all = sorted((float(x.get("Raw_Score") or 0.0) for x in (state.features or [])),
                  reverse=True)
    _rank = (_all.index(_raw) + 1) if _raw in _all else 0
    _top = round(100.0 * _rank / len(_all), 0) if _all else 0
    h = {"symbol": sym, "verdict": f.get("Final AI Bias", "AVOID TRADE"),
         "score": _raw,
         "confidence": int(float(f.get("Score Coverage") or 0)),
         "action": (f"रैंक {_rank}/{len(_all)} · "
                    f"{'टॉप ' + str(max(1, int(_top))) + '%' if _top <= 10 else ('निचला ' + str(max(1, int(100 - _top))) + '%' if _top >= 90 else 'मध्य')} · "
                    f"{len(reasons)} फैक्टर सक्रिय · कवरेज "
                    f"{int(float(f.get('Score Coverage') or 0))}%"),
         "reasons": reasons or [{"v": "0", "hi": "इस स्टॉक पर कोई फैक्टर सक्रिय नहीं"}]}
    render_verdict_card(h)
    render_reasons_popup(h, key=key, breakdown=bd)


def _zone_frame(rows, only_aligned: bool = True) -> pd.DataFrame:
    out = []
    for r in rows:
        tf = r.get("Near Timeframe") or r.get("tf") or "15m"
        sym = r.get("Symbol", "")
        side = r.get("demand/Supply", "")
        bias = r.get("AI Bias", "")
        aligned = ((side == "Demand" and bias in ("BUY", "STRONG BUY")) or
                   (side == "Supply" and bias in ("SELL", "STRONG SELL")))
        if only_aligned and not aligned:
            continue
        _live = _LIVE_PX.get(sym)
        _entry = r.get("Entry (Proximal)")
        try:
            _dist = round((float(_live or r.get("LTP") or 0) - float(_entry))
                          / float(_entry) * 100.0, 2)
        except (TypeError, ValueError, ZeroDivisionError):
            _dist = None
        _fpx, _fwhen = _fut_info(sym, r.get("Futures"))
        out.append({
            "स्टॉक": _chart_url(sym, tf, fut=False),      # नाम ही चार्ट लिंक
            "फ्यूचर्स": _chart_url(sym, tf, fut=True),    # करेंट-मंथ फ्यूचर्स लिंक
            "साइड": side,
            "TF": tf,
            "स्पॉट LTP": _live if _live else r.get("LTP"),
            "स्पॉट समय": _LIVE_STAMP if _live else "स्कैन",
            "फ्यू. LTP": _fpx,
            "फ्यू. समय": _fwhen,
            "दूरी %": abs(_dist) if _dist is not None else None,
            "एंट्री": _entry,
            "SL": r.get("Distal SL"),
            "टारगेट": r.get("Target Price"),
            "Qty": r.get("Qty"),
            "AI स्कोर": r.get("AI Score"),
            "R:R": r.get("R:R"),
            "रिस्क ₹": r.get("Risk ₹"),
            "स्थिति": r.get("Zone State"),
        })
    return pd.DataFrame(out)


def _show_zone_frame(frame: pd.DataFrame, height: int = 0) -> None:
    if frame.empty:
        st.caption("इस फ़िल्टर पर अभी कोई ज़ोन नहीं — ऊपर **🚀 स्कैन** दबाएँ।")
        return
    # height hugs the data: 36 px per row, min 120, max 400 - no blank sheet
    if not height:
        height = max(120, min(400, 38 * (len(frame) + 1)))
    # rows arrive already sorted (nearest zone first, then score)
    styled = (frame.style
              .format({"स्पॉट LTP": "₹{:.2f}", "फ्यू. LTP": "₹{:.2f}",
                       "एंट्री": "₹{:.2f}", "SL": "₹{:.2f}", "दूरी %": "{:.2f}%",
                       "टारगेट": "₹{:.2f}", "रिस्क ₹": "₹{:.0f}", "R:R": "{:.1f}"},
                      na_rep="—")
              .map(lambda v: "color:#089981;font-weight:700;" if v == "Demand"
                   else ("color:#F23645;font-weight:700;" if v == "Supply" else ""),
                   subset=["साइड"])
              .map(lambda v: ("color:#089981;font-weight:700;"
                              if isinstance(v, (int, float)) and v <= 1.5
                              else ("color:#f59e0b;" if isinstance(v, (int, float))
                                    and v <= 4 else "color:#868993;")),
                   subset=["दूरी %"]))
    st.dataframe(styled,
                 column_config={
                     "स्टॉक": st.column_config.LinkColumn(
                         "स्टॉक", display_text=r"symbol=NSE%3A([A-Z0-9%&.-]*)&"),
                     "फ्यूचर्स": st.column_config.LinkColumn(
                         "फ्यूचर्स", display_text=r"symbol=NSE%3A([A-Z0-9%&.-]*)1!&"),
                 },
                 hide_index=True, height=height, **container_kw())


