with tab_market:
    render_breadth(BREADTH, QSNAP.stamp if QSNAP.ok else "—")
    df = pd.DataFrame(state.features)

    # real bhavcopy futures where available
    if not df.empty:
        _fo = BHAV.futures_oi()
        if not _fo.empty:
            _m = _fo.set_index("Symbol")
            _real_ltp = df["Raw_Symbol"].map(_m["Fut LTP"])
            _mask = _real_ltp.notna()
            if _mask.any():
                df.loc[_mask, "Futures LTP (Cur-M)"] = _real_ltp[_mask]
                df.loc[_mask, "Data Source"] = "NSE bhavcopy (EOD)"
                _real_oi = df["Raw_Symbol"].map(_m["Fut OI Chg %"])
                _cur = pd.to_numeric(df["Futures OI Chg %"].astype(str)
                                     .str.replace("%", "", regex=False), errors="coerce")
                _cur = _cur.mask(_real_oi.notna(), _real_oi)
                df["Futures OI Chg %"] = _cur.map(
                    lambda v: f"{v:+.2f}%" if pd.notna(v) else "n/a")
        df["Futures LTP (Cur-M)"] = pd.to_numeric(
            df["Futures LTP (Cur-M)"], errors="coerce").fillna(0.0).round(2)
        # basis must compare like with like: when the futures leg is the official
        # EOD close, the reference is that same session's cash close
        _spot = pd.to_numeric(df["Spot LTP"], errors="coerce")
        _chg = pd.to_numeric(df["Spot Chg %"], errors="coerce").fillna(0.0)
        _prev = _spot / (1 + _chg / 100.0)
        _eod = df["Data Source"].astype(str).str.contains("bhavcopy", na=False)
        try:
            _cash = BHAV.cash_close()
        except Exception:                                        # noqa: BLE001
            _cash = {}
        _same = df["Raw_Symbol"].map(_cash)
        _ref = _same.where(_eod & _same.notna(), _prev.where(_eod, _spot))
        df["Dif. %"] = ((df["Futures LTP (Cur-M)"] - _ref) / _ref * 100).round(2).fillna(0.0)

    if df.empty:
        st.warning("फ़ीड में कोई पंक्ति नहीं — ⚙️ सेटिंग → डेटा सोर्स देखें।")
    else:
        f1, f2, f3 = st.columns([1.6, 1.05, 1.05])
        search = f1.text_input("🔎 स्टॉक", "", key="sym_filter",
                               label_visibility="collapsed", placeholder="🔎 स्टॉक खोजें")
        bias_filter = f2.multiselect("Bias", ["STRONG BUY", "BUY", "AVOID TRADE",
                                              "SELL", "STRONG SELL"], default=[],
                                     label_visibility="collapsed", placeholder="Bias")
        only_news = f3.toggle("न्यूज़ वाले", value=False)

        view = df
        if search:
            view = view[view["Symbol"].str.contains(search.upper(), na=False)]
        if bias_filter:
            view = view[view["Final AI Bias"].isin(bias_filter)]
        if only_news:
            _hit = set((state.notes or {}).get("news_focus", []) or [])
            if _hit:
                view = view[view["Raw_Symbol"].isin(_hit)]

        _vp = st.selectbox("स्टॉक का फैसला + कारण", view["Raw_Symbol"].tolist()[:120],
                           key="verdict_pick", label_visibility="collapsed",
                           help="कोई भी स्टॉक चुनें → नीचे उसका फैसला और 'क्यों?' पॉपअप")
        _vv1, _vv2 = st.columns([1.8, 1])
        with _vv1:
            _verdict_block(str(_vp), key="mkt_why")
        with _vv2:
            st.caption("ℹ️ **क्यों?** = हर फैक्टर का हिंदी कारण + स्रोत (फ्लोटिंग पॉपअप, "
                       "स्क्रीन बदलने की ज़रूरत नहीं)।")

        st.caption(f"**{len(view)}**/{len(df)} नाम · स्टॉक टैप = करेंट-मंथ फ्यूचर्स चार्ट · "
                   f"Zone = सबसे नज़दीकी ज़ोन (TF + दूरी)")
        display_master(view, st.session_state.get("tf_master", "1d"), height=580,
                       zone_map=zone_map_from_state(state))

        _vm = (state.notes or {}).get("verify") or {}
        _sm = (state.notes or {}).get("score_meta") or {}
        _src = " · ".join(f"{k} {v.get('latency_ms', 0):.0f}ms"
                          for k, v in (state.sources or {}).items() if v.get("served"))
        st.caption(
            f"⏱ {state.asof:%d-%b %H:%M:%S} IST · फ़ीड {_src or '—'}"
            + (f" · 2nd स्रोत {_vm.get('source', 'TradingView')} {_vm.get('stamp', '')} → "
               f"{_vm.get('verified', 0)}/{_vm.get('checked', 0)} नाम "
               f"{_vm.get('tol', 0.6)}% के अंदर" if _vm else "")
            + (f" · FII-DII {_sm.get('fii', {}).get('net'):+.0f} Cr"
               if _sm.get("fii", {}).get("net") else ""))

        with st.expander("📡 हर नाम का स्रोत + दूसरा स्रोत (verification sheet)"):
            _pc = [c for c in ["Symbol", "Spot LTP", "Data Source", "Data Mode",
                               "Latency (ms)", "Verify", "TV LTP", "Verify Diff %"]
                   if c in view.columns]
            st.dataframe(view[_pc], hide_index=True, height=300, **container_kw())
            st.caption("स्रोत: NSE bhavcopy → Yahoo → TradingView. **Spot LTP असली** है; जहाँ "
                       "Dhan/nsebhavcopy नहीं है वहाँ फ्यूचर्स LTP/PCR **अनुमानित** है और Status में "
                       "`F अनुमान` लिखा है — छुपाया नहीं जाता। 'Verify' = TradingView का स्वतंत्र भाव; "
                       "⚠ = दोनों स्रोत 0.6% से ज़्यादा अलग।")

        if st.toggle("🔬 ड्रिल-डाउन दिखाएँ — Option chain · Delivery · Indicators",
                     value=st.session_state.get("show_drill", False), key="show_drill"):
            _pick = st.selectbox("स्टॉक", view["Raw_Symbol"].tolist()[:120], key="drill_sym")
            _d1, _d2 = st.columns([1.25, 1])
            with _d1:
                render_option_board(_pick, is_index=False, steps=5)
            with _d2:
                render_delivery([_pick], top=1)
            render_indicators(_pick, TF_DEFAULTS)

        with st.expander("🌍 मैक्रो 8 — स्कोर में कितना योगदान"):
            render_macro_layer(state)

        if st.toggle("💰 FII/DII · 🏭 सेक्टर फ्लो · 📅 5-दिन औसत दिखाएँ",
                     value=st.session_state.get("show_flow", False), key="show_flow"):
            _i1, _i2 = st.columns([1, 1])
            with _i1:
                render_fii_dii()
            with _i2:
                _c = QUOTES.batch_candles(UNIVERSE, "1d", "1mo", ttl=600)
                render_sectors(_c)
            _f5 = five_day(QUOTES.batch_candles(UNIVERSE, "1d", "1mo", ttl=600), QDF)
            if not _f5.empty:
                st.dataframe(
                    _f5.head(40).style.format({"आज %": "{:+.2f}", "5-दिन औसत %": "{:+.2f}",
                                               "अंतर": "{:+.2f}", "टर्नओवर (₹ Cr)": "{:,.1f}"})
                    .map(lambda v: "color:#089981;font-weight:700;"
                         if isinstance(v, (int, float)) and v > 0
                         else "color:#F23645;font-weight:700;"
                         if isinstance(v, (int, float)) and v < 0 else "",
                         subset=["आज %", "5-दिन औसत %", "अंतर"]),
                    hide_index=True, height=300, **container_kw())

